// NB-06 · spec: .qa/e2e/specs/nearby.md 1.6 · две роли · меняет данные (согласие) → в finally оба false.
import { test, expect } from '../../fixtures';
import { openRole, turnOff, meetPair, tapWhenTop, card, NAME, listTitle } from './nearby-helpers';

test.use({ browserName: 'webkit' });

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test.describe.configure({ timeout: 180_000 });
  test('тап по карточке открывает профиль, «חזרה» возвращает в «היו כאן» @iphone @data (#67c751)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    const reg2 = await openRole(browser, 'reg2');
    try {
      await meetPair(reg1, reg2);
      const p = reg1.page;
      await tapWhenTop(p, card(p, NAME.reg2).getByRole('img').first()); // фото карточки, не сердце
      await p.waitForURL(new RegExp(`/profile/${reg2.id}`));
      // Экран списка остаётся в DOM под профилем — проверяем только видимые элементы.
      await expect(p.getByText(NAME.reg2).filter({ visible: true }).first()).toBeVisible();
      await expect(p.getByRole('button', { name: 'אהבתי', exact: true }).filter({ visible: true }).first()).toBeVisible();

      await tapWhenTop(p, p.getByRole('button', { name: 'חזרה' }).filter({ visible: true }).first());
      await p.waitForURL(/\/map\?tab=were-here/);
      await expect(listTitle(p)).toBeVisible();
      await expect(card(p, NAME.reg2)).toBeVisible();
    } finally {
      await turnOff(reg1);
      await turnOff(reg2);
      await reg1.ctx.close();
      await reg2.ctx.close();
    }
  });
});
